import{_ as o,o as e,c as t,am as i}from"./chunks/framework.CiF4W93w.js";const u=JSON.parse('{"title":"数据库_基础知识","description":"","frontmatter":{"title":"数据库_基础知识","excerpt":"数据库_基础知识","date":"2023-12-24 21:45:07","updated":"2023-12-24 21:45:07"},"headers":[],"relativePath":"数据库/Java技术栈_数据库SQL/数据库_基础知识.md","filePath":"数据库/Java技术栈_数据库SQL/数据库_基础知识.md","lastUpdated":null}'),a={name:"数据库/Java技术栈_数据库SQL/数据库_基础知识.md"};function r(d,l,n,c,s,E){return e(),t("div",null,[...l[0]||(l[0]=[i('<p>数据库基础知识包含了数据库设计、管理和操作的核心概念。</p><p>常见的一些概念👇</p><ul><li>数据库和数据库管理系统（DBMS）</li><li>数据模型（关系模型与非关系模型）</li><li>数据库设计 <ul><li>ER图</li><li>数据库范式</li></ul></li><li>元组, 码, 候选码, 主码, 外码, 主属性, 非主属性</li><li>主键和外键</li><li>为什么不推荐使用外键与级联</li><li>存储过程</li><li>数据库设计</li><li>字符集</li></ul><h4 id="sql-结构化查询语言" tabindex="-1">SQL（结构化查询语言） <a class="header-anchor" href="#sql-结构化查询语言" aria-label="Permalink to &quot;SQL（结构化查询语言）&quot;">​</a></h4><ul><li><strong>数据定义语言（DDL）</strong>：定义数据库结构，包括CREATE、ALTER、DROP等命令。</li><li><strong>数据操纵语言（DML）</strong>：用于数据访问和处理，包括INSERT、UPDATE、DELETE、SELECT等命令。</li><li><strong>数据控制语言（DCL）</strong>：用于权限和事务控制，包括GRANT、REVOKE、BEGIN TRANSACTION等。</li></ul><h4 id="ddl-和-dml" tabindex="-1">DDL 和 DML <a class="header-anchor" href="#ddl-和-dml" aria-label="Permalink to &quot;DDL 和 DML&quot;">​</a></h4><p><strong>DDL</strong>代表数据定义语言（Data Definition Language），它用于定义数据库结构，包括创建、修改和删除数据库对象。</p><p><strong>DML</strong>代表数据操作语言（Data Manipulation Language），它用于操作和管理数据库中的数据，包括查询、插入、更新和删除数据</p><h4 id="drop、delete-与-truncate-区别" tabindex="-1">drop、delete 与 truncate 区别? <a class="header-anchor" href="#drop、delete-与-truncate-区别" aria-label="Permalink to &quot;drop、delete 与 truncate 区别?&quot;">​</a></h4><ul><li>drop 移除整个表结构，包括其数据和表定义 不能回滚（DDL)</li><li>delete 删除表中的一行或多行记录 能回滚(DML)</li><li>truncate 删除表中的所有记录 不能回滚（DDL)</li></ul><p>执行速度：一般来说：<code>drop</code> &gt; <code>truncate</code> &gt; <code>delete</code></p><p>在MySQL中，<code>DROP</code>、<code>DELETE</code>和<code>TRUNCATE</code>都是用于移除数据的命令，但它们在用法和影响上有明显的区别：</p><blockquote><ol><li>DELETE</li></ol></blockquote><ul><li><strong>用途</strong>：<code>DELETE</code>用于删除表中的一行或多行记录。</li><li><strong>特点</strong>： <ul><li>可以带有<code>WHERE</code>子句，提供了条件删除的功能。</li><li>影响的行数会记录在事务日志中，因此可以回滚。</li><li>触发器（如果有的话）会被激活。</li><li>较慢，特别是在删除大量数据时，因为它逐行删除。</li></ul></li><li><strong>示例</strong>：<code>DELETE FROM table_name WHERE condition;</code></li></ul><blockquote><ol start="2"><li>TRUNCATE</li></ol></blockquote><ul><li><strong>用途</strong>：<code>TRUNCATE</code>用于删除表中的所有记录。</li><li><strong>特点</strong>： <ul><li>不能带有<code>WHERE</code>子句，它总是删除表中的所有记录。</li><li>执行速度比<code>DELETE</code>快，因为它不逐行删除数据，而是直接移除数据页。</li><li>不记录详细的事务日志，只记录重建空表的操作，因此无法回滚（在某些数据库系统中，<code>TRUNCATE</code>是事务安全的，并且可以回滚）。</li><li>重置表的自增计数器（如果有的话）。</li><li>不触发触发器。</li></ul></li><li><strong>示例</strong>：<code>TRUNCATE TABLE table_name;</code></li></ul><blockquote><ol start="3"><li>DROP</li></ol></blockquote><ul><li><strong>用途</strong>：<code>DROP</code>用于移除整个表结构，包括其数据和表定义。</li><li><strong>特点</strong>： <ul><li>删除表的结构及其数据，释放存储空间。</li><li>不能回滚（一旦执行，表就完全消失了）。</li><li>不触发触发器。</li><li>在删除大量数据且不再需要该表时使用。</li></ul></li><li><strong>示例</strong>：<code>DROP TABLE table_name;</code></li></ul><blockquote><p>总结</p></blockquote><ul><li><strong>删除数据行</strong>：如果需要删除部分数据行，使用<code>DELETE</code>。若需删除所有数据行且表结构仍需保留，使用<code>TRUNCATE</code>。</li><li><strong>删除表</strong>：如果要删除整个表及其数据，使用<code>DROP</code>。</li><li><strong>性能考虑</strong>：当处理大量数据时，<code>TRUNCATE</code>比<code>DELETE</code>更高效。</li><li><strong>事务和回滚</strong>：<code>DELETE</code>操作可以回滚，而<code>TRUNCATE</code>和<code>DROP</code>在大多数情况下不能。</li></ul><p>选择使用哪个命令取决于具体的需求，如是否需要保留表结构、是否需要条件删除或是否关注性能优化。</p><h4 id="数据库设计通常分为哪几步" tabindex="-1">数据库设计通常分为哪几步? <a class="header-anchor" href="#数据库设计通常分为哪几步" aria-label="Permalink to &quot;数据库设计通常分为哪几步?&quot;">​</a></h4><ol><li><strong>需求分析</strong> : 分析用户的需求，包括数据、功能和性能需求。</li><li><strong>概念结构设计</strong> : 主要采用 E-R 模型进行设计，包括画 E-R 图。</li><li><strong>逻辑结构设计</strong> : 通过将 E-R 图转换成表，实现从 E-R 模型到关系模型的转换。</li><li><strong>物理结构设计</strong> : 主要是为所设计的数据库选择合适的存储结构和存取路径。</li><li><strong>数据库实施</strong> : 包括编程、测试和试运行。</li><li><strong>数据库的运行和维护</strong> : 系统的运行与数据库的日常维护</li></ol><hr><p>参考</p><ul><li><a href="https://javaguide.cn/database/basis.html" target="_blank" rel="noreferrer">https://javaguide.cn/database/basis.html</a></li></ul>',26)])])}const _=o(a,[["render",r]]);export{u as __pageData,_ as default};
